88	// --- identity, certificate and key
89	
90	/// A fresh identity: a P-256 key and a self-signed certificate over it
91	/// that never expires in practice (rcgen's default `not_after` is the
92	/// year 4096). Returns the identity and the key as PEM, which goes to
93	/// the Keychain and nowhere else. `server_id` is kept when given: a
94	/// rotated key is a new identity for clients but the same installation.
95	pub fn make_identity(
96	    server_id: Option<Uuid>,
97	    server_name: &str,
98	    listen: Listen,
99	) -> Result<(Identity, String), String> {
100	    let server_id = server_id.unwrap_or_else(Uuid::new_v4);
101	    let key = rcgen::KeyPair::generate().map_err(|e| format!("key: {e}"))?;
102	    let mut params = rcgen::CertificateParams::new(Vec::<String>::new())
103	        .map_err(|e| format!("certificate: {e}"))?;
104	    params.distinguished_name.push(
105	        rcgen::DnType::CommonName,
106	        format!("Switchboard {server_id}"),
107	    );
108	    let cert = params
109	        .self_signed(&key)
110	        .map_err(|e| format!("certificate: {e}"))?;
111	    let der = cert.der().to_vec();
