769	/// until the device hangs up or a deadline passes.
770	fn connection(tcp: TcpStream, shared: &Arc<Shared>, paired: &AtomicBool) -> io::Result<()> {
771	    tcp.set_read_timeout(Some(HANDSHAKE_TIMEOUT))?;
772	    tcp.set_write_timeout(Some(WRITE_TIMEOUT))?;
773	    // A reply is one record and goes out at once; Nagle with the
774	    // device's delayed ACK would otherwise add milliseconds per request.
775	    tcp.set_nodelay(true)?;
776	    let conn = ServerConnection::new(Arc::clone(&shared.tls)).map_err(io::Error::other)?;
777	    let mut stream = StreamOwned::new(conn, tcp);
778	    while stream.conn.is_handshaking() {
779	        stream.conn.complete_io(&mut stream.sock)?;
780	    }
781	    let mut reader = BufReader::new(stream);
782	    let mut first = true;
783	    while let Some(request) = read_request(&mut reader)? {
784	        if first {
785	            reader.get_ref().sock.set_read_timeout(Some(IDLE_TIMEOUT))?;
786	            first = false;
